pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address pool, uint256 amount) public {
        vm.assume(pool != address(0));
        vm.assume(amount > 0);
        // Simulate a curated pool by deploying a minimal helper that will call mintSynth on c
        CuratedPoolCaller caller = new CuratedPoolCaller();
        // The helper needs to be considered a curated pool so prank as the helper's address
        // Before calling, we fund the helper with LP tokens that c expects
        // We need to make _getAddedLPAmount return a non-zero amount, so we send some LP tokens to c from the helper
        // First, deploy a mock LP token (which is just an ERC20) to represent the pool's LP token
        MockERC20 lpToken = new MockERC20("LP", "LP");
        lpToken.mint(address(caller), amount);
        // The helper transfers the LP tokens to c so that c.balanceOf(_pool) > mapSynth_LPBalance[pool]
        vm.startPrank(address(caller));
        lpToken.transfer(address(c), amount);
        // Now call mintSynth on c
        c.mintSynth(address(this), amount);
        vm.stopPrank();
        // After minting, mapSynth_LPBalance for the pool caller should have increased by the LP units received.
        // The invariant: mapSynth_LPBalance[address(caller)] == cumulative LP units received (which is amount in this simple case because _getAddedLPAmount returns the exact delta).
        // Since the mutant omits incrementing mapSynth_LPBalance, it will remain 0, breaking the invariant.
        uint256 balance = c.getmapAddress_LPBalance(address(caller));
        assertEq(balance, amount, "mapSynth_LPBalance should equal received LP units");
    }
}

contract CuratedPoolCaller {}

contract MockERC20 {
    string public name;
    string public symbol;
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;
    uint256 public totalSupply;

    constructor(string memory _name, string memory _symbol) {
        name = _name;
        symbol = _symbol;
    }

    function mint(address to, uint256 amount) external {
        balanceOf[to] += amount;
        totalSupply += amount;
        emit Transfer(address(0), to, amount);
    }

    function transfer(address to, uint256 amount) external returns (bool) {
        balanceOf[msg.sender] -= amount;
        balanceOf[to] += amount;
        emit Transfer(msg.sender, to, amount);
        return true;
    }

    event Transfer(address indexed from, address indexed to, uint256 value);
}

