pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address pool, uint256 amount) public {
        vm.assume(pool != address(0));
        vm.assume(pool != address(c));
        vm.assume(amount > 0);

        // Deploy minimal Pool helper that is curated and can call mintSynth
        MockCuratedPool p = new MockCuratedPool(address(c));
        // p must be a curated pool
        vm.mockCall(
            address(c._DAO().POOLFACTORY()),
            abi.encodeWithSelector(iPOOLFACTORY.isCuratedPool.selector, address(p)),
            abi.encode(true)
        );
        // The DAO call returns the factory address; we need to mock _DAO() to return a DAO that returns the mock factory.
        // Simpler: use a MockDAO that returns controlled addresses.
        // Instead, we mock directly the _DAO() internal call via POOLFACTORY mock.
        // However, _DAO() is internal, we can't directly mock it. Deploy a real DAO-compatible mock.

        // Create a MockDAO that returns the MockPoolFactory address
        MockDAO dao = new MockDAO();
        MockPOOLFACTORY factory = new MockPOOLFACTORY();
        dao.setPoolFactory(address(factory));
        // Set BASE to the DAO address via prank as deployer
        vm.prank(address(this));
        c.BASE = address(dao);
        factory.addCuratedPool(address(p));

        // Ensure pool has LP tokens and call mintSynth
        // mintSynth requires pool to call, and _getAddedLPAmount reads its LP token balance
        // Transfer some LP tokens to the pool contract first
        vm.prank(address(p));
        c.mintSynth(address(0x1234), amount);

        // Now check mapSynth_LPBalance for the pool — in reference it should be > 0, in bug it is 0
        assertTrue(c.mapSynth_LPBalance(address(p)) > 0);
    }
}

interface iPOOLFACTORY {
    function isCuratedPool(address) external view returns (bool);
    function addCuratedPool(address) external;
}

interface iDAO {
    function POOLFACTORY() external view returns (address);
}

contract MockCuratedPool {
    C synth;
    constructor(address _synth) { synth = C(_synth); }
    // Function to call mintSynth as pool
    function callMintSynth(address member, uint256 amount) external {
        synth.mintSynth(member, amount);
    }
    // Give it LP tokens so _getAddedLPAmount returns non-zero
    function transferLP(address from, uint256 amount) external {
        // simulate receiving LP tokens
    }
}

contract MockDAO {
    address public POOLFACTORY;
    function setPoolFactory(address _f) external { POOLFACTORY = _f; }
}

contract MockPOOLFACTORY {
    mapping(address => bool) private _curated;
    function isCuratedPool(address p) external view returns (bool) { return _curated[p]; }
    function addCuratedPool(address p) external { _curated[p] = true; }
}

