pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(uint256 amount1, uint256 amount2) public {
        // Keep amounts in admissible wide domain
        uint256 max = type(uint256).max / 2;
        amount1 = bound(amount1, 1, max);
        amount2 = bound(amount2, 1, max);

        // We simulate two mints from the same pool (address(this)).
        // The reference C tracks LP balance by the pool token increase; the bug adds a constant 1.
        // After two mints, the change in mapSynth_LPBalance must equal the change in pool token balance.
        uint256 beforeLPBal1 = c.mapSynth_LPBalance(address(this));
        uint256 beforePoolBal1 = c.balanceOf(address(this));

        vm.prank(address(this));
        c.mintSynth(address(this), amount1);

        uint256 afterLPBal1 = c.mapSynth_LPBalance(address(this));
        uint256 afterPoolBal1 = c.balanceOf(address(this));

        uint256 deltaLP1 = afterLPBal1 - beforeLPBal1;
        uint256 deltaPool1 = afterPoolBal1 - beforePoolBal1;

        // Second mint with a different amount
        uint256 beforeLPBal2 = c.mapSynth_LPBalance(address(this));
        uint256 beforePoolBal2 = c.balanceOf(address(this));

        vm.prank(address(this));
        c.mintSynth(address(this), amount2);

        uint256 afterLPBal2 = c.mapSynth_LPBalance(address(this));
        uint256 afterPoolBal2 = c.balanceOf(address(this));

        uint256 deltaLP2 = afterLPBal2 - beforeLPBal2;
        uint256 deltaPool2 = afterPoolBal2 - beforePoolBal2;

        // For the reference, both deltas must be consistent for each mint.
        // The bug makes deltaLP2 == 1 while deltaPool2 can be arbitrary, so total LP balance change
        // over both mints equals deltaPool1 + deltaPool2, not deltaPool1 + 1.
        // General rule: total LP balance increase over the two mints equals total pool token balance increase.
        uint256 totalDeltaLP = (afterLPBal2 - beforeLPBal1);
        uint256 totalDeltaPool = (afterPoolBal2 - beforePoolBal1);
        assertTrue(totalDeltaLP == totalDeltaPool);
    }
}

