        vm.assume(attacker != address(0) && attacker != address(c));
        vm.assume(poolAddr != address(0) && poolAddr != address(c) && poolAddr != attacker);
        vm.assume(mintAmount > 0 && mintAmount < type(uint256).max / 10**18);
        vm.prank(attacker);
        try c.mintSynth(attacker, mintAmount) {} catch {}
        uint256 lpBalance = c.mapSynth_LPBalance(poolAddr);
        assertTrue(lpBalance == 0);
    }
}

